compile.workshop:
variables {
    global:
        0: code
        1: n
}

rule ("case and default") {
    event {
        Ongoing - Global;
    }
    actions {
        If(True);
            Skip(Value In Array(Array(1, 0), Add(1, Index Of Array Value(Array(Custom String("")), Global.code))));
        //__label_switch_2_0__:
        Set Global Variable(n, 1);
        //__label_switch_2_default__:
        Set Global Variable(n, 2);
        End;
    }
}

